import { NextRequest, NextResponse } from "next/server";
import { connectDB } from "@/lib/db";
import { User } from "@/lib/models/User";
import { Tweet } from "@/lib/models/Tweet";
import { Demerit } from "@/lib/models/Demerit";
import { Notification } from "@/lib/models/Notification";
import { Hashtag } from "@/lib/models/Hashtag";
import { moderateContent, getSuspensionThreshold } from "@/lib/ai-moderation";
import { verifyToken } from "@/lib/auth";
import { extractHashtags, extractMentions } from "@/lib/utils-twitter";

export async function POST(request: NextRequest) {
  try {
    const authHeader = request.headers.get("authorization");
    const token = authHeader?.split(" ")[1];

    if (!token) {
      return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
    }

    const user = verifyToken(token);
    if (!user) {
      return NextResponse.json({ error: "Invalid token" }, { status: 401 });
    }

    const body = await request.json();
    const { content, media } = body;

    if (!content || content.trim().length === 0) {
      return NextResponse.json(
        { error: "Content is required" },
        { status: 400 }
      );
    }

    await connectDB();

    const dbUser = await User.findById(user.userId);
    if (dbUser?.isSuspended) {
      return NextResponse.json(
        { error: "Your account is suspended" },
        { status: 403 }
      );
    }

    const moderation = await moderateContent(content);

    if (moderation.shouldBlock) {
      await User.updateOne(
        { _id: dbUser?._id },
        { $inc: { demeritPoints: moderation.points } }
      );

      const tweet = await Tweet.create({
        content,
        author: dbUser?._id,
        isFlagged: true,
        flagReason: moderation.reason,
        isDeleted: true,
      });

      await Demerit.create({
        user: dbUser?._id,
        tweet: tweet._id,
        reason: moderation.reason,
        points: moderation.points,
        toxicityScore: moderation.toxicityScore,
        content,
      });

      const updatedUser = await User.findById(dbUser?._id);
      if (
        updatedUser &&
        updatedUser.demeritPoints >= getSuspensionThreshold()
      ) {
        await User.updateOne({ _id: dbUser?._id }, { isSuspended: true });
      }

      return NextResponse.json(
        {
          error: `Tweet blocked due to ${moderation.reason}. Demerits: ${moderation.points}`,
        },
        { status: 400 }
      );
    }

    const hashtags = extractHashtags(content);
    const mentions = extractMentions(content);

    const mentionedUsers = await User.find({ username: { $in: mentions } });
    const mentionedUserIds = mentionedUsers.map((u) => u._id);

    const tweet = await Tweet.create({
      content,
      author: dbUser?._id,
      media: media || [],
      hashtags,
      mentions: mentionedUserIds,
    });

    // Update hashtag counts
    for (const tag of hashtags) {
      await Hashtag.findOneAndUpdate(
        { tag },
        { $inc: { count: 1 }, trending: true },
        { upsert: true }
      );
    }

    // Create notifications for mentions
    for (const mentionedUserId of mentionedUserIds) {
      await Notification.create({
        user: mentionedUserId,
        actor: dbUser?._id,
        type: "mention",
        tweet: tweet._id,
      });
    }

    const populatedTweet = (await Tweet.findById(tweet._id)
      .populate("author")
      .lean()) as any;

    return NextResponse.json({
      tweet: {
        ...populatedTweet,
        id: populatedTweet?._id,
        author: {
          ...(populatedTweet?.author as any),
          id: (populatedTweet?.author as any)?._id,
        },
        likes: (populatedTweet?.likes as any[])?.length || 0,
        retweets: (populatedTweet?.retweets as any[])?.length || 0,
        replies: (populatedTweet?.replies as any[])?.length || 0,
      },
    });
  } catch (error: any) {
    console.error("Create tweet error:", error);
    return NextResponse.json(
      { error: error.message || "Failed to create tweet" },
      { status: 500 }
    );
  }
}
